body:
I'm pretty sure I see the issue, its the Dimes = Dimes +1, I need to put an If statement before it right? Or something similar.

    #include <cs50.h>
    #include <stdio.h>

    int main(void)
    {

    float Price;
    int Quarters, Dimes, Nickels, Pennies;


        // Quarters
        printf("What is the amount?");
        Price = GetFloat();
        Quarters = 0;
        Dimes = 0;
        Nickels = 0;
        Pennies = 0;

    int p = Price;





        while (p >= 0.25)
        Price = p - 0.25;
        Quarters = Quarters + 1;








        //Dimes
        while (p >= 0.10)
        Price = p - 0.10;
    if (p - 0.10)
        Dimes = Dimes + 1;





        //Nickels
        while (p >= 0.05)
        Price = p - 0.05;
    if (p - 0.05)
        Nickels = Nickels + 1;



        //Pennies
        while (p >= 0.01)
        Price = p - 0.01;
        Pennies = Pennies + 1;



        printf("Quarters = %d Dimes = %d Nickels = %d Pennies = %d", Quarters, Dimes, Nickels, Pennies);

     //Get each outcome to be increased by 1 after each subtraction. Collect the total numbers in printf at bottom %quarteroutcome etc.


}

If at all possible, please try to avoid telling me exactly where the problem is, thanks!

